import './render-v3.js';
import {WEAPONS,buyWeapon} from './combat.js';
import {CHARACTERS,CHAPTERS,STREET_JOBS} from './story.js';
import {activeLanguage,ENGLISH,translate} from './i18n.js';
import {setLanguage,installLocalization,localizeDOM} from './i18n.js';
import {CARS,PAINTS,MISSIONS,clamp,formatTime,district,distance,routeTo,WORLD_SIZE,nearbyBuildings,roadCoord,roadIndex} from './core.js';
import {normalizeProfile,tunedCar,buyRegion,buySafehouse,buyUpgrade,buyCar,performService,runEarnings,UPGRADE_CATALOG,SAFEHOUSE_PRICES} from './progression.js';
import {EQUIPMENT,equipmentTransaction,emptyArsenal} from './equipment.js';
import {REGIONS,regionAt,regionOpen,setUnlockedRegions,pointDrivable,nearestRoadNode} from './world.js';
import {difficultyFor} from './pursuit.js';
import {Simulation} from './simulation.js';
import {Renderer,drawCar} from './render.js';
import {AudioEngine} from './audio.js';
const $=id=>document.getElementById(id);
const STORAGE_KEY='redline-city-v1';
function load(){try{return normalizeProfile(JSON.parse(localStorage.getItem(STORAGE_KEY)));}catch{return normalizeProfile(null);}}
const profile=load();if(!profile.unlocked.includes(profile.selected))profile.selected='comet';setLanguage(profile.settings.language);
let mode='story',state='menu',modalType='',lastState='menu',sim=new Simulation({demo:true,mapId:profile.mapId||'real'}),toastUntil=0,frame=0,accumulator=0,lastTime=0,uiTimer=0,lastRescue=-100,gamepadPause=false,gamepadConfirm=false,gamepadConnected=false,resultSaved=false,navTimer=0;
let aimPointer=null,mouseFire=false;
const settings=profile.settings,renderer=new Renderer($('game'),sim,settings),audio=new AudioEngine(settings),keys=new Set(),touch={left:false,right:false,throttle:false,brake:false,handbrake:false,nitro:false};
let interact=false,actions={},saveTimer=0,padActions={};const fmt=n=>Math.floor(n).toLocaleString(settings.language==='en'?'en-US':'tr-TR');
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(profile));}catch{toast('Tarayıcı kaydı kapalı; bu oturumda oynamaya devam edebilirsin.');}}
function bestScore(){return mode==='chaos'?profile.chaosBest[profile.chaosStars]:profile.best[mode]||0;}
function refreshMenu(){
 $('menu-best').textContent=Math.floor(bestScore()).toString().padStart(6,'0');$('menu-wallet').textContent='₺ '+fmt(profile.wallet);$('car-count').textContent=String(profile.unlocked.length).padStart(2,'0')+' / '+CARS.length;
 document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.mode===mode));
 $('chaos-settings').classList.toggle('hidden',mode!=='chaos');$('region-count').textContent='0'+profile.regions.length+' / 04';
 document.querySelectorAll('[data-stars]').forEach(b=>{const active=Number(b.dataset.stars)===profile.chaosStars;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});
 $('chaos-description').textContent=difficultyFor(profile.chaosStars).label+' · takip hiç kesilmez · kazanç ×'+(1+(profile.chaosStars-1)*.2).toFixed(1);
 $('play').firstElementChild.textContent=mode==='story'?'POLATIN HİKÂYESİNE BAŞLA':mode==='free'?'ŞEHRE ÇIK':mode==='chaos'?'SONSUZ KAOSU BAŞLAT':'KOVALAMACAYI BAŞLAT';
}
function setTouch(){const active=settings.touch==='on'||settings.touch==='auto'&&matchMedia('(pointer: coarse)').matches;document.body.classList.toggle('touch',active);$('touch-controls').classList.toggle('hidden',!active||state!=='playing');}
function clearInput(){keys.clear();Object.keys(touch).forEach(k=>touch[k]=false);document.querySelectorAll('#touch-controls .pressed').forEach(b=>b.classList.remove('pressed'));interact=false;actions={};mouseFire=false;}
function start(){
 clearInput();audio.init();sim=new Simulation({carId:profile.selected,carSpec:tunedCar(profile),color:profile.color,mode,chaosStars:profile.chaosStars,regions:profile.regions,safehouses:profile.safehouses,spawnRegion:profile.spawnRegion,arsenal:profile.arsenal[profile.selected],mapId:profile.mapId||'real',storyState:profile.story,armory:profile.armory});renderer.setSim(sim);state='playing';lastState='playing';modalType='';resultSaved=false;accumulator=0;lastRescue=-100;
 $('menu').classList.add('hidden');$('hud').classList.remove('hidden');$('modal').classList.add('hidden');$('map-screen').classList.add('hidden');$('toast').classList.remove('show');
 $('mode-label').textContent=mode==='story'?'HİKÂYE':mode==='free'?'SERBEST':mode==='chaos'?'KAOS '+profile.chaosStars+'★':'KOVALAMACA';setTouch();toast(mode==='story'?'POLAT · H İLE HİKÂYE · HARİTADAKİ HEDEFE GİT':mode==='free'?'ŞEHİR SENİN · DRIFT İLE PUAN TOPLA':'POLİS ENSENDE · DÖNÜŞTE EL FRENİNİ KULLAN',4200);updateHUD();
}
function goMenu(){clearInput();state='menu';modalType='';sim=new Simulation({demo:true,mapId:profile.mapId||'real'});renderer.setSim(sim);$('menu').classList.remove('hidden');$('hud').classList.add('hidden');$('modal').classList.add('hidden');$('map-screen').classList.add('hidden');setTouch();refreshMenu();}
function toast(text,ms=2600){$('toast').textContent=text;$('toast').classList.add('show');toastUntil=performance.now()+ms;}
function openModal(type,html){if(state!=='modal')lastState=state;state='modal';modalType=type;clearInput();$('modal-content').innerHTML=html;localizeDOM($('modal-content'));$('modal-content').parentElement.classList.toggle('wide',['city','workshop'].includes(type));const heading=$('modal-content').querySelector('h2');if(heading)heading.id='modal-title';$('modal').classList.remove('hidden');$('modal-close').classList.toggle('hidden',type==='result'||type==='dialogue');setTouch();setTimeout(()=>($('modal-content').querySelector('button')||$('modal-close')).focus(),30);}
function closeModal(){if(modalType==='result'||modalType==='dialogue')return;state=lastState;modalType='';$('modal').classList.add('hidden');clearInput();setTouch();}
function pause(){if(state==='playing'){openModal('pause',`<div class="eyebrow">MOTOR SOĞUSUN. SEN DE BİR NEFES AL.</div><h2>KISA BİR<br><em>MOLA.</em></h2><p>Kaçışın seni bekliyor. Şu ana kadar <b>${fmt(sim.score)}</b> puan topladın.</p><button id="resume" class="primary">DEVAM ET <span>↗</span></button><button id="pause-retry" class="secondary">YENİDEN BAŞLA</button><button id="pause-settings" class="secondary">AYARLAR</button><button id="pause-finish" class="secondary">TURU BİTİR / KAZANCI AL</button><button id="pause-exit" class="secondary">ANA MENÜYE DÖN</button><p class="tip">Turu bitirerek normal kazancını alabilirsin. Kovalamacada takipten kurtulup kendi sığınağına girmek %35 bonus verir. Kaosta sığınak ve kaçış yoktur.</p>`);$('resume').onclick=closeModal;$('pause-retry').onclick=start;$('pause-settings').onclick=()=>showSettings('playing');$('pause-exit').onclick=goMenu;$('pause-finish').onclick=()=>{sim.finish(false);results();};}else if(state==='modal'&&modalType==='pause')closeModal();}
function showHelp(){openModal('help',`<div class="eyebrow">KISA KILAVUZ / UZUN KOVALAMACA</div><h2>İZİNİ<br><em>KAYBETTİR.</em></h2><p>Viraja girerken gazı bırakmadan el frenine dokun. Arka taraf açılınca direksiyonu toparla, çıkışta nitroyu bas.</p><div class="control-list"><kbd>WASD / OK TUŞLARI</kbd><span>Gaz, fren / geri vites ve direksiyon</span><kbd>F</kbd><span>Araçtan in / yakındaki araca bin</span><kbd>FARE / J</kbd><span>Yaya: nişan al / ateş et</span><kbd>1–6 / R / B</kbd><span>Silah / şarjör / ilk yardım</span><kbd>H / O</kbd><span>Hikâye defteri / silah alışverişi</span><kbd>SPACE</kbd><span>Araçta el freni · yaya kaçınma</span><kbd>SHIFT</kbd><span>Araçta nitro · yaya koşu</span><kbd>E</kbd><span>Serviste alışveriş / takip bittiyse kendi sığınağında bankala</span><kbd>Q / Z / C</kbd><span>Arka cama ateş / lastik mayını / yağ bırak</span><kbd>R</kbd><span>Sıkışırsan yola dön · %12 kaporta gider</span><kbd>M</kbd><span>Şehir haritası · oyunu duraklatır</span><kbd>ESC / P</kbd><span>Oyunu duraklat</span></div><p class="tip">Polisleri peşine diz, son anda keskin dön. Birbirlerine hızla çarptıklarında patlarlar; yakın araçlar da zincire katılır. Binalarla arana mesafe koy, Yıldıza göre 20–28 saniye görünmez kal. Helikopter 4 yıldızda gelir; kapalı geçitler hava görüşünü keser. Kaosta takip hiç bitmez.</p><p>✚ Tamir &nbsp; · &nbsp; ϟ Nitro &nbsp; · &nbsp; ₺ Para<br>Oyun kumandası: sol çubuk yön, RT gaz, LT fren, A drift, B nitro, X servis, LB mayın, RB yağ, Y araçtan in / bin, Start mola. Ekipman ve mühimmatı Araç Geliştir menüsünden al.</p><button id="help-done" class="primary">ANLAŞILDI. GAZLA. <span>↗</span></button>`);$('help-done').onclick=closeModal;}
function showGarage(){
 openModal('garage',`<div class="eyebrow">BİR ARAÇ. BİR KARAKTER.</div><h2>GARAJ.</h2><div class="garage-balance">₺ ${fmt(profile.wallet)}</div><div class="car-list">${CARS.map(car=>{const owned=profile.unlocked.includes(car.id),selected=profile.selected===car.id;return `<button class="car-card ${selected?'selected':''}" data-car="${car.id}" aria-label="${car.name}, ${owned?'kullanılabilir':car.price+' lira'}"><canvas width="220" height="100" data-car-preview="${car.id}"></canvas><h3>${car.name}</h3><small>${car.tag}</small>${['HIZ','DRIFT','ZIRH'].map((label,i)=>`<div class="car-stat"><span>${label}</span><i style="width:${car.stats[i]*.75}%"></i></div>`).join('')}<span class="price">${selected?'✓ SEÇİLİ':owned?'SEÇ →':'₺ '+fmt(car.price)+' · KİLİTLİ'}</span></button>`;}).join('')}</div><div class="paint-swatches"><span>BOYA</span>${PAINTS.map(color=>`<button data-paint="${color}" class="${profile.color===color?'active':''}" style="background:${color}" aria-label="Araç rengi ${color}"></button>`).join('')}</div><p id="garage-message">Turlardan kazandığın parayla yeni arabaların kilidini aç.</p><button id="garage-upgrades" class="secondary">MODİFİYE / EKİPMAN ATÖLYESİ ↗</button><button id="garage-done" class="primary">SOKAĞA DÖN <span>↗</span></button>`);
 document.querySelectorAll('[data-car-preview]').forEach(canvas=>{const spec=CARS.find(c=>c.id===canvas.dataset.carPreview),ctx=canvas.getContext('2d');ctx.scale(2.2,2.2);drawCar(ctx,{x:50,y:23,angle:-.12,width:spec.width,length:spec.length,color:spec.id===profile.selected?profile.color:spec.color,spec,type:'player'});});
 document.querySelectorAll('[data-car]').forEach(button=>button.onclick=()=>{const result=buyCar(profile,button.dataset.car);if(!result.ok){$('garage-message').textContent=result.message;return;}save();showGarage();refreshMenu();});
 $('garage-upgrades').onclick=showWorkshop;
 document.querySelectorAll('[data-paint]').forEach(button=>button.onclick=()=>{profile.color=button.dataset.paint;save();showGarage();});$('garage-done').onclick=closeModal;
}

function transaction(result,render){if(result.ok){save();refreshMenu();render();}toast(result.message,3500);}
function showWorkshop(){
 const car=CARS.find(c=>c.id===profile.selected),u=profile.upgrades[car.id]||{},kit=profile.arsenal[car.id]||emptyArsenal(),spec=tunedCar(profile);
 openModal('workshop',`<div class="eyebrow">${car.name} / MODİFİYE ATÖLYESİ</div><h2>HAZIRLAN.</h2><div class="shop-balance">CÜZDAN <b>₺ ${fmt(profile.wallet)}</b></div><p>${Math.round(spec.speed*.3)} km/h · ${spec.health} kaporta. Parçalar seçili araca özeldir. Değişiklikler yeni turda kullanılır.</p><div class="upgrade-grid">${UPGRADE_CATALOG.map(item=>{const level=u[item.id]||0;return `<article class="shop-card"><div class="shop-card-head"><h3>${item.name}</h3><b>${level}/3</b></div><p>${item.detail}</p><div class="upgrade-level">${[1,2,3].map(i=>'<i class="'+(level>=i?'filled':'')+'"></i>').join('')}</div><button data-upgrade="${item.id}" ${level>=3?'disabled':''}>${level>=3?'TAM GELİŞTİRİLDİ':'KADEME '+(level+1)+' · ₺'+fmt(item.prices[level])}</button></article>`;}).join('')}</div><div class="shop-section"><span>TAKİP KIRICI EKİPMANLAR</span><small>İlk mühimmat satın alıma dahil</small></div><div class="equipment-grid">${EQUIPMENT.map(e=>{const owned=kit.owned.includes(e.id),equipped=kit.equipped.includes(e.id),refill=Math.ceil(e.refill*(e.capacity-kit.ammo[e.id])/e.capacity);return `<article class="shop-card equipment-card"><div class="shop-card-head"><span class="equipment-icon">${e.icon}</span><kbd>${e.key}</kbd></div><h3>${e.name}</h3><p>${e.detail}</p>${owned?'<div class="ammo-stock">MÜHİMMAT <b>'+kit.ammo[e.id]+' / '+e.capacity+'</b></div>':''}<button data-equipment="${e.id}" data-action="${owned?'toggle':'buy'}">${owned?(equipped?'✓ TAKILI · SÖK':'ARACA TAK'):'SATIN AL · ₺'+fmt(e.price)}</button>${owned?'<button data-equipment="'+e.id+'" data-action="refill" '+(refill===0?'disabled':'')+'>'+ (refill===0?'MÜHİMMAT DOLU':'DOLDUR · ₺'+fmt(refill))+'</button>':''}</article>`;}).join('')}</div><p class="tip">Taret arkaya ateş eder. Mayın ve yağ sadece takipçi polisleri etkiler. Q / F / C tuşları veya ekrandaki ekipman düğmelerini kullan. Mühimmat harcadıkça kaydedilir.</p><button id="workshop-done" class="primary">HAZIRIM <span>↗</span></button>`);
 document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>transaction(buyUpgrade(profile,car.id,b.dataset.upgrade),showWorkshop));
 document.querySelectorAll('[data-equipment]').forEach(b=>b.onclick=()=>transaction(equipmentTransaction(profile,car.id,b.dataset.equipment,b.dataset.action),showWorkshop));$('workshop-done').onclick=closeModal;
}
function showCity(){
 openModal('city',`<div class="eyebrow">İSTANBUL'DAN ESİNLENEN DÖRT BÖLGE</div><h2>İKİ YAKA.<br><em>TEK KAÇIŞ.</em></h2><div class="shop-balance">CÜZDAN <b>₺ ${fmt(profile.wallet)}</b></div><p>Ruhsatlar KURGU İSTANBUL haritasını genişletir. GERÇEK GALATA ayrı bir OpenStreetMap haritasıdır; bütün sokakları açıktır. Mekânlar ve karakterler kurgusaldır.</p><div class="city-grid">${REGIONS.map((r,i)=>{const open=profile.regions.includes(r.id),home=profile.safehouses.includes(r.id),start=profile.spawnRegion===r.id;return `<article class="shop-card region-card ${open?'open-region':''}" style="--region-color:${r.color}"><div class="shop-card-head"><span>0${i+1} / ${open?'AÇIK':'KİLİTLİ'}</span><b>${open?'✓':'◇'}</b></div><h3>${r.name}</h3><small>${r.subtitle}</small><p>${r.description}</p>${!open?'<button data-region="'+r.id+'">RUHSAT AL · ₺'+fmt(r.price)+'</button>':!home?'<button data-home="'+r.id+'">SIĞINAK AL · ₺'+fmt(SAFEHOUSE_PRICES[r.id])+'</button>':'<button data-spawn="'+r.id+'" '+(start?'disabled':'')+'>'+ (start?'✓ BAŞLANGIÇ BÖLGEN':'SONRAKİ TURA BURADA BAŞLA')+'</button>'}</article>`;}).join('')}</div><p class="tip">Sığınaklar takip bittikten sonra bankalama ve sonraki tura başlangıç noktası sağlar. Ücretli tamir ve nitro servisleri açık bölgelerde herkesin kullanımına açıktır. Kaosta sığınak takibi sonlandırmaz.</p><button id="city-done" class="primary">ŞEHRE DÖN <span>↗</span></button>`);
 const sync=()=>{setUnlockedRegions(sim.world,profile.regions);sim.safehouses=[...profile.safehouses];sim.cops.forEach(c=>c.routeTimer=0);renderer.drawMap($('big-map'),true);showCity();};
 document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>transaction(buyRegion(profile,b.dataset.region),sync));document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>transaction(buySafehouse(profile,b.dataset.home),sync));document.querySelectorAll('[data-spawn]').forEach(b=>b.onclick=()=>{profile.spawnRegion=b.dataset.spawn;save();showCity();toast('Sonraki turun başlangıç noktası değişti.');});$('city-done').onclick=closeModal;
}

function showSettings(from='menu'){
 openModal('settings',`<div class="eyebrow">KENDİ SÜRÜŞÜNÜ AYARLA</div><h2>AYARLAR.</h2><div class="setting-row"><span>Dil / Language</span><select id="setting-language" aria-label="Dil / Language" data-no-i18n><option value="tr" ${settings.language==='tr'?'selected':''}>Türkçe</option><option value="en" ${settings.language==='en'?'selected':''}>English</option></select></div><div class="setting-row"><span>Motor, siren ve efektler</span><button id="setting-sound">${settings.sound?'AÇIK':'KAPALI'}</button></div><div class="setting-row"><span>Ses seviyesi</span><input id="setting-volume" type="range" min="0" max="100" value="${settings.volume*100}" aria-label="Ses seviyesi"></div><div class="setting-row"><span>Synth radyo</span><button id="setting-music">${settings.music?'AÇIK':'KAPALI'}</button></div><div class="setting-row"><span>Kamera sarsıntısı / patlama flaşı</span><button id="setting-shake">${settings.shake?'AÇIK':'KAPALI'}</button></div><div class="setting-row"><span>Şehrin atmosferi</span><select id="setting-night"><option value="false" ${!settings.night?'selected':''}>AKŞAMÜSTÜ</option><option value="true" ${settings.night?'selected':''}>GECE</option></select></div><div class="setting-row"><span>Görüntü kalitesi</span><select id="setting-quality"><option value="high" ${settings.quality==='high'?'selected':''}>YÜKSEK</option><option value="low" ${settings.quality==='low'?'selected':''}>PERFORMANS</option></select></div><div class="setting-row"><span>Dokunmatik kontroller</span><select id="setting-touch">${[['auto','OTOMATİK'],['on','AÇIK'],['off','KAPALI']].map(([v,l])=>`<option value="${v}" ${settings.touch===v?'selected':''}>${l}</option>`).join('')}</select></div><p>Ayarların, garajın ve rekorların bu tarayıcıda otomatik saklanır.</p><button id="settings-done" class="primary">TAMAM <span>↗</span></button>`);lastState=from;
 for(const key of ['sound','music','shake'])$('setting-'+key).onclick=()=>{settings[key]=!settings[key];$('setting-'+key).textContent=settings[key]?'AÇIK':'KAPALI';audio.init();audio.setSettings();save();};
 $('setting-language').onchange=e=>{settings.language=e.target.value;setLanguage(settings.language);save();};
 $('setting-volume').oninput=e=>{settings.volume=Number(e.target.value)/100;audio.setSettings();save();};$('setting-night').onchange=e=>{settings.night=e.target.value==='true';save();};$('setting-quality').onchange=e=>{settings.quality=e.target.value;renderer.resize();save();};$('setting-touch').onchange=e=>{settings.touch=e.target.value;setTouch();save();};$('settings-done').onclick=closeModal;
}
function results(){
 if(resultSaved)return;resultSaved=true;
 const score=Math.floor(sim.score),isRecord=score>bestScore(),earnings=runEarnings(sim);profile.wallet+=earnings;profile.best[mode]=Math.max(profile.best[mode]||0,score);if(mode==='chaos')profile.chaosBest[sim.chaosStars]=Math.max(profile.chaosBest[sim.chaosStars],score);profile.totals.wrecks+=sim.wrecks;profile.totals.escapes+=sim.escapes;profile.totals.runs++;
 profile.runs.unshift({score,mode,stars:sim.chaosStars,win:sim.win,time:Math.floor(sim.time),wrecks:sim.wrecks,date:new Date().toISOString()});profile.runs=profile.runs.slice(0,10);save();
 openModal('result',`<div class="eyebrow">${isRecord?'YENİ REKOR. SOKAKLAR SENDEN BAHSEDİYOR.':sim.win?'BU TUR SENİN.':'BİR TUR DAHA. DAHA SERT BİR DÖNÜŞ.'}</div><h2>${sim.win?'TEMİZ KAÇIŞ.':'TUR<br><em>TAMAMLANDI.</em>'}</h2><div class="result-grid"><div class="big-result"><span>TOPLAM SKOR</span><b>${fmt(score)}</b></div><div><span>SÜRE</span><b>${formatTime(sim.time)}</b></div><div><span>POLİS SAF DIŞI</span><b>${sim.wrecks}</b></div><div><span>EN YÜKSEK HIZ</span><b>${Math.round(sim.maxSpeed)} <small>km/h</small></b></div><div><span>EN UZUN DRIFT</span><b>${sim.longestDrift.toFixed(1)} <small>sn</small></b></div><div><span>TAKİPTEN KURTULMA</span><b>${sim.escapes}</b></div><div><span>CÜZDANA EKLENDİ ${sim.win?'· %35 BONUS':mode==='chaos'?'· '+sim.chaosStars+'★ KAOS':''}</span><b style="color:var(--orange)">₺ ${fmt(earnings)}</b></div></div><button id="retry" class="primary">BİR TUR DAHA <span>↗</span></button><button id="result-menu" class="secondary">ANA MENÜ / GARAJ</button>`);$('retry').onclick=start;$('result-menu').onclick=goMenu;refreshMenu();
}
function toggleMap(){
 if(state==='playing'){state='map';clearInput();$('map-screen').classList.remove('hidden');renderer.drawMap($('big-map'),true);setTouch();}
 else if(state==='map'){state='playing';$('map-screen').classList.add('hidden');setTouch();}
}
function setDestination(point){
 if(!regionOpen(sim.world,point)){showCity();return;}let {x,y}=point;
 if(!pointDrivable(sim.world,{x,y},20)){const n=nearestRoadNode(sim.world,{x,y});if(!n)return;({x,y}=n);}
 sim.waypoint={x,y,name:point.name||'İŞARETLİ HEDEF',garage:point.id!==undefined};sim.navRoute=routeTo(sim.world,sim.player,sim.waypoint);$('map-tip').textContent='Hedef: '+sim.waypoint.name;renderer.drawMap($('big-map'),true);
}
function nearestGarage(){const g=sim.world.garages.filter(g=>regionOpen(sim.world,g)&&profile.safehouses.includes(g.id)).sort((a,b)=>distance(a,sim.player)-distance(b,sim.player))[0];if(g)setDestination(g);if(state==='playing')toast('EN YAKIN SIĞINAK İŞARETLENDİ');}
function showRecords(){
 const totals=profile.totals,badges=[['LASTİK USTASI',Math.max(...Object.values(profile.best))>=1000],['POLİS KABUSU',totals.wrecks>=10],['HAYALET',totals.escapes>=3],['MÜDAVİM',totals.runs>=5],['KOLEKSİYONCU',profile.unlocked.length===CARS.length]];
 openModal('records',`<div class="eyebrow">HER TUR BİR İZ BIRAKIR.</div><h2>SOKAK<br><em>SİCİLİ.</em></h2><div class="result-grid"><div><span>TAMAMLANAN TUR</span><b>${fmt(totals.runs)}</b></div><div><span>SAF DIŞI POLİS</span><b>${fmt(totals.wrecks)}</b></div></div><div class="badge-list">${badges.map(([name,earned])=>`<span class="badge ${earned?'earned':''}">${earned?'★':'◇'} ${name}</span>`).join('')}</div><div class="record-list">${profile.runs.length?profile.runs.map((r,i)=>`<div class="record-row"><span>${String(i+1).padStart(2,'0')}</span><div>${r.mode==='story'?'HİKÂYE':r.mode==='free'?'SERBEST':r.mode==='chaos'?'KAOS '+r.stars+'★':r.mode==='timed'?'ESKİ KAOS':'KOVALAMACA'}<small>${r.win?'TEMİZ KAÇIŞ':'TUR TAMAMLANDI'}</small></div><span>${formatTime(r.time)}</span><b>${fmt(r.score)}</b></div>`).join(''):'<p>İlk turunu tamamla. Rekorların ve son 10 sürüşün burada görünsün.</p>'}</div><button id="records-done" class="primary">SOKAĞA DÖN <span>↗</span></button>`);$('records-done').onclick=closeModal;
}
function updateHUD(){
 const p=sim.player,speed=Math.round(p.speed*.3),health=clamp(p.hp/p.maxHp*100,0,100);
 $('score').textContent=Math.floor(sim.score).toString().padStart(6,'0');$('record-label').querySelector('i').textContent=fmt(bestScore());$('district').textContent=district(p);$('speed').textContent=speed;$('gear').textContent=p.vx*Math.cos(p.angle)+p.vy*Math.sin(p.angle)<-10?'R':speed<3?'N':Math.min(6,1+Math.floor(speed/28));
 $('gauge').style.strokeDashoffset=290-clamp(speed/220,0,1)*290;$('health').style.width=health+'%';$('health').style.background=health<30?'#ee7753':'#becda6';$('health-number').textContent=Math.ceil(health);$('nitro').style.width=p.nitro+'%';$('nitro-number').textContent=Math.floor(p.nitro);
 $('wanted').innerHTML='★'.repeat(sim.heatLevel)+'<span>'+'★'.repeat(5-sim.heatLevel)+'</span>';$('wanted').parentElement.classList.toggle('searching',sim.searching);$('pursuit-state').textContent=mode==='free'?'SOKAKLAR SAKİN':mode==='chaos'?'KAOS '+sim.chaosStars+'★ · TAKİP KESİLMEZ':sim.heli.visible?'HELİKOPTER SENİ GÖRÜYOR':sim.searching?(sim.covered?'ÜSTÜN KAPALI · GİZLİ KAL':'ARANIYORSUN · GİZLİ KAL'):sim.pursuit?'TAKİP EDİLİYORSUN':'İZİNİ KAYBETTİRDİN';$('escape-bar').firstElementChild.style.width=clamp(sim.escape/sim.escapeRequired*100,0,100)+'%';
 $('run-time').textContent=formatTime(sim.time);$('wrecks').textContent=sim.wrecks;
 $('combo').classList.toggle('active',sim.comboTime>0&&sim.combo>5);$('combo-caption').textContent=sim.comboCaption;$('combo-points').textContent='+ '+fmt(sim.combo);$('combo-multiplier').textContent='×'+sim.comboMultiplier.toFixed(1);$('combo-bar').style.width=clamp(sim.comboTime/2.3*100,0,100)+'%';
 const mission=sim.missionList[sim.mission];if(mission){const count=clamp(sim[mission.stat],0,mission.target);$('mission-index').textContent=String(sim.mission+1).padStart(2,'0');$('mission-title').textContent=mission.title;$('mission-desc').textContent=mission.desc;$('mission-progress').style.width=count/mission.target*100+'%';$('mission-count').textContent=fmt(count)+' / '+fmt(mission.target);}else{$('mission-title').textContent='Şehrin efsanesi';$('mission-desc').textContent='Bütün görevler tamam. Rekorunu büyüt.';$('mission-progress').style.width='100%';$('mission-count').textContent=sim.missionList.length+' / '+sim.missionList.length;}
 $('interaction').classList.toggle('hidden',!sim.garage&&!sim.service);$('interaction').querySelector('span').textContent=sim.service?(sim.service.type==='repair'?'TAMİR +%65 · ₺180':'NİTRO DOLDUR · ₺100'):mode==='chaos'?'KAOSTA SIĞINAK KULLANILMAZ':sim.garage&&!profile.safehouses.includes(sim.garage.id)?'SATILIK SIĞINAK · HARİTADAN AL':sim.pursuit?'ÖNCE TAKİBİ ATLAT':'SIĞINAĞA GİR · KAZANCI BANKALA';
 const kit=sim.equipment.kit;for(const e of EQUIPMENT){const b=$('equip-'+e.id),owned=kit.equipped.includes(e.id);b.classList.toggle('unavailable',!owned);b.querySelector('b').textContent=owned?kit.ammo[e.id]:'—';b.querySelector('small').textContent=!owned?'TAKILI DEĞİL':e.id==='turret'?sim.equipment.turretOn?'OTOMATİK':'BEKLEMEDE':sim.equipment.cooldowns[e.id]>.1?sim.equipment.cooldowns[e.id].toFixed(1)+' sn':'HAZIR';} $('hud-wallet').textContent='₺ '+fmt(profile.wallet);$('sound-toggle').textContent=settings.sound?'SES AÇIK':'SES KAPALI';renderer.drawMap($('radar'));
 $('navigation').classList.toggle('hidden',!sim.waypoint);
 if(sim.waypoint){const d=distance(p,sim.waypoint);$('nav-distance').textContent=d>1000?(d/1000).toFixed(1)+' KM':Math.round(d)+' M';$('nav-name').textContent=sim.waypoint.name;const target=sim.navRoute?.find(q=>distance(p,q)>100)||sim.waypoint;$('nav-arrow').style.transform=`rotate(${Math.atan2(target.y-p.y,target.x-p.x)+Math.PI/2}rad)`;if(d<60){toast(sim.waypoint.garage?'HEDEFE ULAŞTIN · GARAJDA E İLE BANKALA':'HEDEFE ULAŞTIN');sim.waypoint=null;sim.navRoute=[];}}
}
function getInput(){
 const foot=sim.human?.onFoot,pad=navigator.getGamepads?.()?.find(g=>g?.connected);let mx=(keys.has('KeyD')||keys.has('ArrowRight')||touch.right?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')||touch.left?1:0),my=(keys.has('KeyS')||keys.has('ArrowDown')||touch.brake?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')||touch.throttle?1:0);
 let throttle=my<0?1:0,brake=my>0?1:0,steer=mx,handbrake=keys.has('Space')||touch.handbrake,nitro=keys.has('ShiftLeft')||keys.has('ShiftRight')||touch.nitro,fire=mouseFire||keys.has('KeyJ')||touch.fire,aim=aimPointer?{x:renderer.camera.x+(aimPointer.x-renderer.w/2)/renderer.camera.zoom,y:renderer.camera.y+(aimPointer.y-renderer.h/2)/renderer.camera.zoom}:null;
 if(pad){mx=Math.abs(pad.axes[0]||0)>.13?pad.axes[0]:mx;my=Math.abs(pad.axes[1]||0)>.13?pad.axes[1]:my;steer=mx;throttle=Math.max(throttle,pad.buttons[7]?.value||0);brake=Math.max(brake,pad.buttons[6]?.value||0);handbrake||=pad.buttons[0]?.pressed;nitro||=pad.buttons[1]?.pressed;if(foot){fire||=pad.buttons[7]?.pressed;const ax=pad.axes[2]||0,ay=pad.axes[3]||0;if(Math.hypot(ax,ay)>.3)aim={x:sim.player.x+ax*400,y:sim.player.y+ay*400};}for(const [name,index] of [['mine',4],['oil',5],['vehicle',3],['interact',2]]){const down=!!pad.buttons[index]?.pressed;if(down&&!padActions[name]){if(name==='interact')interact=true;else actions[name]=true;}padActions[name]=down;}}
 const extra=actions;actions={};const action=interact;interact=false;sim.player.braking=!!brake;return {throttle,brake,steer,handbrake,nitro,moveX:mx,moveY:my,sprint:nitro,fire,aim,roll:extra.roll||foot&&touch.handbrake,rearFire:keys.has('KeyQ')||touch.rearFire,interact:action,...extra};
}
function tick(now){
 const elapsed=Math.min(.06,((now-lastTime)||16)/1000);lastTime=now;
 const pad=navigator.getGamepads?.()?.find(g=>g?.connected);if(pad){const paused=!!pad.buttons[9]?.pressed,confirm=!!pad.buttons[0]?.pressed;if(paused&&!gamepadPause){if(state==='modal'&&modalType==='pause')closeModal();else if(state==='playing')pause();}if(confirm&&!gamepadConfirm&&(state==='menu'||state==='modal'&&modalType==='result'))start();gamepadPause=paused;gamepadConfirm=confirm;}
 if(state==='playing'||state==='menu'){
  accumulator+=elapsed;const input=state==='playing'&&accumulator>=1/60?getInput():{};let loops=0;
  while(accumulator>=1/60&&loops++<5){const step=sim.slowmo>0?1/100:1/60;sim.update(step,input);input.interact=input.mine=input.oil=input.turretToggle=input.vehicle=input.reload=input.roll=input.medkit=false;input.weaponSlot=0;accumulator-=1/60;
   for(const event of sim.events){if(state!=='menu'){audio.event(event);if(event.type==='service'){const r=performService(profile,sim.player,event.kind);toast(r.message);if(r.ok)save();}if(event.type==='ammo'){const a=profile.arsenal[sim.player.spec.id];if(a){a.ammo[event.id]=event.remaining;if(!saveTimer)saveTimer=setTimeout(()=>{saveTimer=0;save();},500);}}if(event.type==='dialogue')showDialogue(event);if(event.type==='story-save'){profile.story=structuredClone(event.state);profile.wallet+=event.reward||0;save();}if(event.type==='armory-save'){profile.armory=structuredClone(event.armory);if(!saveTimer)saveTimer=setTimeout(()=>{saveTimer=0;save();},500);}if(['toast','mission','escape'].includes(event.type))toast(event.text,event.type==='escape'?3500:2600);if(event.type==='end')results();}}sim.events=[];
   if(state!=='playing'&&state!=='menu')break;
  }
 }else accumulator=0;
 renderer.render(elapsed);audio.update(sim,state==='playing');
 uiTimer+=elapsed;if(uiTimer>.08&&state==='playing'){updateHUD();uiTimer=0;}
 navTimer+=elapsed;if(navTimer>.7&&state==='playing'&&sim.waypoint&&!sim.human?.interior){sim.navRoute=routeTo(sim.world,sim.player,sim.waypoint);navTimer=0;}
 if(now>toastUntil)$('toast').classList.remove('show');frame=requestAnimationFrame(tick);
}
$('city-open').onclick=showCity;$('workshop-open').onclick=showWorkshop;$('map-shop').onclick=showCity;
 document.querySelectorAll('[data-stars]').forEach(b=>b.onclick=()=>{profile.chaosStars=Number(b.dataset.stars);save();refreshMenu();});
