 document.querySelectorAll('[data-language]').forEach(b=>b.onclick=()=>{settings.language=b.dataset.language;setLanguage(settings.language);save();refreshMenu();});
 $('play').onclick=start;$('garage-open').onclick=showGarage;$('help-open').onclick=showHelp;$('settings-open').onclick=()=>showSettings('menu');$('modal-close').onclick=closeModal;$('pause-button').onclick=pause;$('map-toggle').onclick=toggleMap;$('map-close').onclick=toggleMap;$('interaction').onclick=()=>interact=true;
$('sound-toggle').onclick=()=>{settings.sound=!settings.sound;audio.init();audio.setSettings();save();updateHUD();};
