$('help-open').onclick=()=>{showHelp();const hint=document.createElement('p');hint.className='tip';hint.textContent='G tuşu en yakın garajı işaretler. Haritada istediğin noktaya dokunarak da rota oluşturabilirsin.';$('modal-content').insertBefore(hint,$('help-done'));if(location.protocol!=='file:'){const link=document.createElement('a');link.className='offline-link';link.href='REDLINE-Offline.html';link.download='REDLINE-Offline.html';link.textContent='↓ Çevrimdışı oyunu indir';$('modal-content').append(link);}};
$('big-map').addEventListener('click',e=>{if(sim.human?.interior)return;const rect=$('big-map').getBoundingClientRect(),pt={x:(e.clientX-rect.left)/rect.width*sim.world.size,y:(e.clientY-rect.top)/rect.height*sim.world.size};const place=[...sim.world.garages,...sim.world.services].sort((a,b)=>distance(a,pt)-distance(b,pt)).find(g=>distance(g,pt)<120);setDestination(place||pt);});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;refreshMenu();});
window.addEventListener('keydown',e=>{
 if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Tab'].includes(e.code)&&state==='playing')e.preventDefault();
 if(e.repeat){keys.add(e.code);return;}
 if(e.code==='Escape'||e.code==='KeyP'){if(state==='map')toggleMap();else if(state==='modal'&&modalType!=='result')closeModal();else pause();return;}
 if(e.code==='KeyM'){toggleMap();return;}
 if(e.code==='KeyG'&&state==='playing'){nearestGarage();return;}
 if(e.code==='Enter'&&state==='menu'){start();return;}
 if(state==='playing'){if(e.code==='KeyF')actions.vehicle=true;if(e.code==='KeyZ')actions.mine=true;if(e.code==='KeyC')actions.oil=true;if(e.code==='Space'&&sim.human.onFoot)actions.roll=true;if(e.code==='KeyB')actions.medkit=true;if(/^Digit[1-6]$/.test(e.code))actions.weaponSlot=Number(e.code.at(-1));if(e.code==='KeyH'){showJournal();return;}if(e.code==='KeyO'){showArmory();return;}}
 if(e.code==='KeyE'&&state==='playing')interact=true;
 if(e.code==='KeyR'&&state==='playing'){if(sim.human?.onFoot){actions.reload=true;return;}if(sim.time-lastRescue>=8){sim.rescue();lastRescue=sim.time;}else toast('YOLA DÖNMEK İÇİN BİRKAÇ SANİYE BEKLE');}
 keys.add(e.code);
});
document.addEventListener('keydown',e=>{if(e.key==='Tab'&&state==='modal'){const focusables=[...$('modal').querySelectorAll('button:not(.hidden),select,input,a[href]')].filter(el=>el.offsetParent!==null);const first=focusables[0],last=focusables.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(state==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(state==='playing')pause();}});
window.addEventListener('resize',()=>{renderer.resize();setTouch();});
document.querySelectorAll('#touch-controls [data-key]').forEach(button=>{const key=button.dataset.key;button.addEventListener('pointerdown',e=>{e.preventDefault();touch[key]=true;button.classList.add('pressed');button.setPointerCapture(e.pointerId);audio.init();});for(const event of ['pointerup','pointercancel','lostpointercapture'])button.addEventListener(event,()=>{touch[key]=false;button.classList.remove('pressed');});button.addEventListener('contextmenu',e=>e.preventDefault());});
