Object.defineProperty(window,'redlineSnapshot',{get:()=>({state,mode,time:sim.time,score:sim.score,player:{x:sim.player.x,y:sim.player.y,speed:sim.player.speed,hp:sim.player.hp,nitro:sim.player.nitro},cops:sim.cops.length,wrecks:sim.wrecks,heat:sim.heatLevel,escape:sim.escape,garage:!!sim.garage,particles:sim.particles.length})});

const v3Text=(tr,en)=>settings.language==='en'?en:tr;
function showDialogue(event){let page=0;const draw=()=>{const line=event.pages[page],last=page===event.pages.length-1;openModal('dialogue','<div class="dialogue '+(event.dream?'dream':'')+'"><div class="eyebrow">'+v3Text('GALATA GÜNLÜKLERİ','GALATA CHRONICLES')+'</div><div class="dialogue-portrait">'+line[0].slice(0,1)+'</div><h2>'+line[0]+'</h2><p class="dialogue-line">'+line[settings.language==='en'?2:1]+'</p><small>'+(page+1)+' / '+event.pages.length+'</small>'+(last&&event.choices?'<div class="choice-row"><button id="dialogue-choice">'+v3Text('Gerçeği paylaş. Birlikte ilerle.','Share the truth. Face it together.')+'</button><button id="dialogue-alt">'+v3Text('Tehlikeyi kendine sakla.','Keep the danger to yourself.')+'</button></div>':'<button id="dialogue-next" class="primary">'+(last?v3Text('YOLA DEVAM','CONTINUE'):v3Text('DEVAM','NEXT'))+' ↗</button>')+'</div>');const done=choice=>{sim.story.resolve(choice);state='playing';lastState='playing';modalType='';$('modal').classList.add('hidden');clearInput();setTouch();};if(last&&event.choices){$('dialogue-choice').onclick=()=>done(0);$('dialogue-alt').onclick=()=>done(1);}else $('dialogue-next').onclick=()=>{if(last)done(0);else{page++;draw();}};};draw();}
function showJournal(){const current=sim.story.current(),story=lastState==='menu'||state==='menu'?profile.story:sim.story.state;openModal('journal','<div class="eyebrow">POLAT / GALATA</div><h2>'+v3Text('HİKÂYE DEFTERİ','STORY JOURNAL')+'</h2><p>'+v3Text('Ailesi tehdit edilen sıradan bir insan. Elif ile kurduğu sakin hayat hayali, onu hem hayatta tutuyor hem de kararlarını sorgulatıyor.','An ordinary man whose family is threatened. His dream of a quiet life with Elif keeps him alive and makes him question his choices.')+'</p><div class="shop-balance">'+v3Text('BÖLÜM','CHAPTER')+' <b>'+Math.min(story.index+1,18)+' / 18</b></div><p>'+v3Text('Elifin güveni','Elif’s trust')+': '+story.trust+' · '+v3Text('Bitirilen işler','Jobs finished')+': '+story.jobs+'</p><div class="chapter-list">'+CHAPTERS.map((m,i)=>'<div class="chapter '+(i===story.index?'current':'')+'"><b>'+String(i+1).padStart(2,'0')+'</b><span>'+v3Text(m.title,m.en)+'</span><small>'+(i<story.index?'✓':i===story.index?v3Text('AKTİF','ACTIVE'):'◇')+'</small></div>').join('')+'</div><h3>'+v3Text('SOKAK İŞLERİ','STREET JOBS')+'</h3><div class="upgrade-grid">'+STREET_JOBS.map(j=>'<button class="secondary" data-job="'+j.id+'">'+v3Text(j.tr,j.en)+' · ₺'+j.reward+'</button>').join('')+'</div><h3>'+v3Text('TANIŞTIĞIN İNSANLAR','THE PEOPLE OF GALATA')+'</h3>'+CHARACTERS.map(c=>'<p><b>'+c[0]+'</b> — '+c[settings.language==='en'?2:1]+'</p>').join('')+'<button id="journal-close" class="primary">'+v3Text('KAPAT','CLOSE')+' ↗</button>');document.querySelectorAll('[data-job]').forEach(b=>b.onclick=()=>{if(lastState==='menu')start();else closeModal();sim.story.startJob(b.dataset.job);});$('journal-close').onclick=closeModal;}
function showArmory(){openModal('armory','<div class="eyebrow">POLAT / '+v3Text('ÇANTA','LOADOUT')+'</div><h2>'+v3Text('SİLAHLAR','WEAPONS')+'</h2><div class="shop-balance">'+v3Text('CÜZDAN','WALLET')+' <b>₺ '+fmt(profile.wallet)+'</b></div><p>'+v3Text('1–6 ile silah seç. Fareyle nişan al, sol tıkla ateş et. R doldur, B ilk yardım.','Select with 1–6. Aim with the mouse, fire with left click. R reloads, B uses a medkit.')+'</p><div class="upgrade-grid">'+WEAPONS.map((w,i)=>{const a=profile.armory[w.id];return '<article class="shop-card"><div class="shop-card-head"><h3>'+(i+1)+' · '+v3Text(w.name,w.en)+'</h3><b>'+w.mag+'</b></div><p>'+v3Text('Hasar','Damage')+' '+w.damage+(w.pellets>1?' × '+w.pellets:'')+' · '+v3Text('Menzil','Range')+' '+w.range+'</p><p>'+v3Text('Mühimmat','Ammo')+': '+a.ammo+'</p><button data-weapon="'+w.id+'" data-refill="'+a.owned+'">'+(a.owned?v3Text('MÜHİMMAT AL','BUY AMMO'):v3Text('SATIN AL','BUY')+' · ₺'+w.price)+'</button></article>';}).join('')+'</div><button id="armory-close" class="primary">'+v3Text('HAZIRIM','READY')+' ↗</button>');document.querySelectorAll('[data-weapon]').forEach(b=>b.onclick=()=>{const result=buyWeapon(profile,b.dataset.weapon,b.dataset.refill==='true');if(result.ok){sim.human.armory=structuredClone(profile.armory);for(const w of WEAPONS)sim.human.clip[w.id]=Math.min(w.mag,sim.human.armory[w.id].ammo);save();showArmory();}toast(result.message);});$('armory-close').onclick=closeModal;}
function updateV3HUD(){const h=sim.human;if(!h)return;document.body.classList.toggle('on-foot',h.onFoot);$('foot-hud').classList.toggle('hidden',!h.onFoot);$('health-label').textContent=h.onFoot?v3Text('CAN','HEALTH'):v3Text('KAPORTA','BODY');$('nitro-label').textContent=h.onFoot?v3Text('DAYANIKLILIK','STAMINA'):v3Text('NİTRO','NITRO');if(h.onFoot){const w=WEAPONS.find(w=>w.id===h.weaponId);$('foot-weapon').textContent=v3Text(w.name,w.en);$('foot-ammo').textContent=h.clip[w.id]+' / '+Math.max(0,h.armory[w.id].ammo-h.clip[w.id]);$('foot-state').textContent=h.reloadTimer>0?v3Text('DOLDURULUYOR','RELOADING'):v3Text('R DOLDUR · B İLK YARDIM','R RELOAD · B MEDKIT');$('foot-stamina').style.width=h.avatar.stamina+'%';$('nitro').style.width=h.avatar.stamina+'%';$('nitro-number').textContent=Math.floor(h.avatar.stamina);if(h.interaction){$('interaction').classList.remove('hidden');$('interaction').querySelector('span').textContent=translate(h.interaction.name)+' · E';}else if(!h.interior&&distance(h.avatar,h.vehicle)<100){$('interaction').classList.remove('hidden');$('interaction').querySelector('span').textContent=v3Text('F · ARACA BİN','F · ENTER CAR');}}
 if(mode==='story'){const o=sim.story.objective();$('mission-title').textContent=o.title;$('mission-desc').textContent=o.desc;$('mission-count').textContent=Math.floor(o.progress)+' / '+o.total;$('mission-progress').style.width=Math.min(100,o.progress/o.total*100)+'%';$('mode-label').textContent=v3Text('POLATIN HİKÂYESİ','POLAT’S STORY');if(!h.interior&&sim.story.target()&&(!sim.waypoint||sim.waypoint.storyAuto)){const l=sim.story.target();if(sim.waypoint?.id!==l.id){sim.waypoint={...l,storyAuto:true};sim.navRoute=routeTo(sim.world,sim.player,l);}}}
 if(!h.onFoot)$('foot-hud').classList.add('hidden');if(h.interior)$('navigation').classList.add('hidden');if(h.interior)$('district').textContent=h.interior.location.name;else if(sim.world.mapKind==='real')$('district').textContent='GALATA — KARAKÖY';$('map-credit').classList.toggle('hidden',sim.world.mapKind!=='real');$('equip-turret').querySelector('small').textContent=h.onFoot?'—':v3Text('Q BASILI TUT','HOLD Q');}
